{"version":3,"file":"technology.js","sources":["pages/technology/technology.vue","../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvdGVjaG5vbG9neS90ZWNobm9sb2d5LnZ1ZQ"],"sourcesContent":["<template>\n  <view class=\"container\">\n    <!-- 标题 -->\n    <view class=\"header\">\n      <text class=\"title\">兴趣分类</text>\n      <text class=\"subtitle\">点击叶子节点可添加/删除兴趣</text>\n    </view>\n\n    <!-- 兴趣树列表 -->\n    <scroll-view scroll-y class=\"tree-container\">\n      <view \n        v-for=\"item in visibleTree\" \n        :key=\"item.id\" \n        class=\"list-item\"\n        :style=\"{ paddingLeft: `${item.level * 20 + 15}px` }\"\n        :class=\"{ 'active': interestIds.has(item.id) }\"\n      >\n        <!-- 展开/折叠图标 -->\n        <text \n          v-if=\"item.children?.length\"\n          class=\"expand-icon\"\n          @click.stop=\"toggleExpand(item)\"\n        >\n          {{ item.expanded ? '▼' : '▶' }}\n        </text>\n        <text v-else class=\"expand-placeholder\"></text>\n        \n        <!-- 节点内容 -->\n        <view \n          class=\"item-content\"\n          @click=\"item.isLeaf ? handleItemClick(item) : null\"\n        >\n          <text class=\"item-text\">{{ item.name }}</text>\n          <view class=\"badges\">\n            <text v-if=\"item.level > 0\" class=\"level-badge\">L{{ item.level }}</text>\n            <text v-if=\"interestIds.has(item.id)\" class=\"selected-badge\">已选</text>\n          </view>\n        </view>\n      </view>\n    </scroll-view>\n\n    <!-- 操作按钮 -->\n    <view class=\"action-bar\">\n      <button class=\"refresh-btn\" @click=\"getInterest\">刷新兴趣列表</button>\n    </view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, computed } from \"vue\"\nimport { onLoad } from '@dcloudio/uni-app'\nimport { listAll, getMyInterest, addMyInterest, deleteMyInterest } from \"../../api/api\"\n\n// 原始数据\nconst treeData = ref([])\nconst interestIds = ref(new Set())\nconst expandedKeys = ref(new Set())\n\n// 获取兴趣数据\nconst getInterest = async () => {\n  try {\n    const res = await getMyInterest()\n    interestIds.value = new Set(res.map(item => item.id))\n    uni.showToast({\n      title: '兴趣列表已更新',\n      icon: 'success'\n    })\n  } catch (error) {\n    console.error(\"兴趣查询失败:\", error)\n    uni.showToast({\n      title: '查询失败',\n      icon: 'error'\n    })\n  }\n}\n\n// 处理节点点击\nconst handleItemClick = async (item) => {\n  const isInterested = interestIds.value.has(item.id)\n  \n  uni.showActionSheet({\n    title: `操作: ${item.name}`,\n    itemList: isInterested ? ['移除兴趣'] : ['添加兴趣'],\n    success: async (res) => {\n      try {\n        if (isInterested) {\n          await deleteMyInterest(item.id)\n          interestIds.value.delete(item.id)\n          uni.showToast({\n            title: '已移除',\n            icon: 'success'\n          })\n        } else {\n          await addMyInterest(item.id)\n          interestIds.value.add(item.id)\n          uni.showToast({\n            title: '已添加',\n            icon: 'success'\n          })\n        }\n      } catch (error) {\n        uni.showToast({\n          title: '操作失败',\n          icon: 'error'\n        })\n      }\n    }\n  })\n}\n\n// 展开/折叠节点\nconst toggleExpand = (item) => {\n  expandedKeys.value.has(item.id) \n    ? expandedKeys.value.delete(item.id)\n    : expandedKeys.value.add(item.id)\n}\n\n// 构建可见树\nconst visibleTree = computed(() => {\n  const result = []\n  const traverse = (nodes, level = 0, parentExpanded = true) => {\n    nodes.forEach(node => {\n      const isExpanded = expandedKeys.value.has(node.id)\n      if (level === 0 || parentExpanded) {\n        result.push({ \n          ...node, \n          level,\n          expanded: isExpanded,\n          isLeaf: !node.children?.length\n        })\n      }\n      if (node.children && isExpanded) {\n        traverse(node.children, level + 1, isExpanded)\n      }\n    })\n  }\n  traverse(treeData.value)\n  return result\n})\n\n// 构建树形结构\nconst buildTree = (data) => {\n  const map = {}\n  const roots = []\n  \n  data.forEach(item => {\n    map[item.id] = { ...item, children: [] }\n  })\n  \n  data.forEach(item => {\n    item.parentId \n      ? map[item.parentId]?.children.push(map[item.id])\n      : roots.push(map[item.id])\n  })\n  \n  return roots\n}\n\n// 初始化数据\nconst listAllInterest = async () => {\n  const res = await listAll()\n  treeData.value = buildTree(res)\n  if (treeData.value.length) {\n    expandedKeys.value.add(treeData.value[0].id)\n  }\n}\n\nonLoad(() => {\n  listAllInterest()\n  getInterest()\n})\n</script>\n\n<style>\n/* 基础样式 */\n.container {\n  display: flex;\n  flex-direction: column;\n  height: 100vh;\n  background-color: #f8f9fa;\n  padding: 0;\n}\n\n/* 头部样式 */\n.header {\n  padding: 20px 16px 10px;\n  background-color: #fff;\n  border-bottom: 1px solid #eee;\n}\n\n.title {\n  font-size: 18px;\n  font-weight: 600;\n  color: #333;\n  display: block;\n}\n\n.subtitle {\n  font-size: 12px;\n  color: #999;\n  margin-top: 4px;\n  display: block;\n}\n\n/* 树容器 */\n.tree-container {\n  flex: 1;\n  padding: 8px 0;\n  background-color: #fff;\n}\n\n/* 列表项样式 */\n.list-item {\n  display: flex;\n  align-items: center;\n  padding: 12px 16px;\n  transition: all 0.2s;\n  border-left: 4px solid transparent;\n}\n\n.list-item.active {\n  background-color: #f0f7ff;\n  border-left-color: #1890ff;\n}\n\n.list-item:active {\n  background-color: #e6f7ff;\n}\n\n/* 展开图标 */\n.expand-icon {\n  width: 24px;\n  height: 24px;\n  text-align: center;\n  line-height: 24px;\n  color: #666;\n  margin-right: 8px;\n  font-size: 12px;\n}\n\n.expand-placeholder {\n  width: 24px;\n}\n\n/* 内容区域 */\n.item-content {\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.item-text {\n  font-size: 15px;\n  color: #333;\n}\n\n/* 徽章样式 */\n.badges {\n  display: flex;\n  gap: 6px;\n}\n\n.level-badge {\n  font-size: 10px;\n  padding: 2px 6px;\n  background-color: #f0f0f0;\n  color: #666;\n  border-radius: 10px;\n}\n\n.selected-badge {\n  font-size: 10px;\n  padding: 2px 6px;\n  background-color: #1890ff;\n  color: white;\n  border-radius: 10px;\n}\n\n/* 操作栏 */\n.action-bar {\n  padding: 12px 16px;\n  background-color: #fff;\n  border-top: 1px solid #eee;\n}\n\n.refresh-btn {\n  background-color: #1890ff;\n  color: white;\n  border-radius: 4px;\n  font-size: 14px;\n}\n\n/* 层级指示器 */\n.list-item[style*=\"padding-left: 15px\"] {\n  background-color: #f9f9f9;\n}\n\n.list-item[style*=\"padding-left: 35px\"] {\n  background-color: #fcfcfc;\n}\n</style>","import MiniProgramPage from 'D:/uniapp/myJoinup/joinup/pages/technology/technology.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","getMyInterest","uni","deleteMyInterest","addMyInterest","computed","listAll","onLoad","MiniProgramPage"],"mappings":";;;;;;AAsDA,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,cAAcA,cAAAA,IAAI,oBAAI,KAAK;AACjC,UAAM,eAAeA,cAAAA,IAAI,oBAAI,KAAK;AAGlC,UAAM,cAAc,YAAY;AAC9B,UAAI;AACF,cAAM,MAAM,MAAMC,sBAAe;AACjC,oBAAY,QAAQ,IAAI,IAAI,IAAI,IAAI,UAAQ,KAAK,EAAE,CAAC;AACpDC,sBAAAA,MAAI,UAAU;AAAA,UACZ,OAAO;AAAA,UACP,MAAM;AAAA,QACZ,CAAK;AAAA,MACF,SAAQ,OAAO;AACdA,sBAAAA,MAAA,MAAA,SAAA,yCAAc,WAAW,KAAK;AAC9BA,sBAAAA,MAAI,UAAU;AAAA,UACZ,OAAO;AAAA,UACP,MAAM;AAAA,QACZ,CAAK;AAAA,MACF;AAAA,IACH;AAGA,UAAM,kBAAkB,OAAO,SAAS;AACtC,YAAM,eAAe,YAAY,MAAM,IAAI,KAAK,EAAE;AAElDA,oBAAAA,MAAI,gBAAgB;AAAA,QAClB,OAAO,OAAO,KAAK,IAAI;AAAA,QACvB,UAAU,eAAe,CAAC,MAAM,IAAI,CAAC,MAAM;AAAA,QAC3C,SAAS,OAAO,QAAQ;AACtB,cAAI;AACF,gBAAI,cAAc;AAChB,oBAAMC,QAAgB,iBAAC,KAAK,EAAE;AAC9B,0BAAY,MAAM,OAAO,KAAK,EAAE;AAChCD,4BAAAA,MAAI,UAAU;AAAA,gBACZ,OAAO;AAAA,gBACP,MAAM;AAAA,cAClB,CAAW;AAAA,YACX,OAAe;AACL,oBAAME,QAAa,cAAC,KAAK,EAAE;AAC3B,0BAAY,MAAM,IAAI,KAAK,EAAE;AAC7BF,4BAAAA,MAAI,UAAU;AAAA,gBACZ,OAAO;AAAA,gBACP,MAAM;AAAA,cAClB,CAAW;AAAA,YACF;AAAA,UACF,SAAQ,OAAO;AACdA,0BAAAA,MAAI,UAAU;AAAA,cACZ,OAAO;AAAA,cACP,MAAM;AAAA,YAChB,CAAS;AAAA,UACF;AAAA,QACF;AAAA,MACL,CAAG;AAAA,IACH;AAGA,UAAM,eAAe,CAAC,SAAS;AAC7B,mBAAa,MAAM,IAAI,KAAK,EAAE,IAC1B,aAAa,MAAM,OAAO,KAAK,EAAE,IACjC,aAAa,MAAM,IAAI,